/* MODULE kn09 · Bước 5 Chọn kênh · PR và truyền thông khủng hoảng
   10 bài × 7 câu. Mọi thương hiệu gặp khủng hoảng trong module đều là HƯ CẤU; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kn09', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kn09-01', skill:'comm', read:'6 phút', t:'Câu chuyện của bạn có đáng thành tin không?',
  situation:'Hãng sữa hạt hư cấu Mộc An sắp ra dòng sữa óc chó mới. Phòng marketing muốn "lên báo" nên soạn bản tin: "Mộc An ra mắt sản phẩm mới chất lượng cao, thơm ngon, bổ dưỡng." Gửi 30 phóng viên, không ai đăng. Cùng lúc, một bạn trong nhóm R&D kể rằng Mộc An vừa ký thu mua óc chó với 120 hộ dân ở Lào Cai, giá cao hơn thương lái 15%.',
  concept:{ name:'Giá trị tin tức (news value)',
    body:'Nhà báo không đăng vì bạn muốn được đăng; họ đăng vì độc giả của họ muốn đọc. Một câu chuyện có giá trị tin tức khi có ít nhất một trong các yếu tố: <b>mới</b> (lần đầu, khác thường), <b>gần</b> (liên quan tới người đọc), <b>con người</b> (có nhân vật, có số phận), <b>xung đột hoặc thay đổi</b>, và <b>con số cụ thể</b> kiểm chứng được. "Sản phẩm mới chất lượng cao" không có yếu tố nào — đó là quảng cáo. Việc của người làm PR là đào trong doanh nghiệp để tìm góc có tin, rồi để sản phẩm đi kèm theo.' },
  example:'Góc "120 hộ dân Lào Cai bán óc chó cao hơn giá thương lái 15%" có con người, có thay đổi, có con số. Mộc An gửi lại cho 30 phóng viên, kèm ảnh một hộ trồng và số liệu thu nhập. Có 6 bài đăng, tỉ lệ 20% — sản phẩm được nhắc ở đoạn cuối mỗi bài. Cùng một doanh nghiệp, cùng một tháng; thứ khác là góc câu chuyện.',
  takeaway:'Nhà báo đăng thứ độc giả muốn đọc; hãy tìm góc có tin trong doanh nghiệp, để sản phẩm đi kèm.',
  apply:'Chọn một doanh nghiệp bạn biết. Trong 60 giây, nêu một góc có tin (mới, gần, con người, thay đổi, con số) mà không nhắc tới tính năng sản phẩm.',
  mistakes:['Coi mô tả sản phẩm là tin tức và thất vọng khi báo không đăng.','Thêm tính từ "đột phá", "hàng đầu" thay vì thêm con số và nhân vật.'],
  q:[
  { type:'mcq', stem:'Bản tin "Mộc An ra mắt sản phẩm mới chất lượng cao" gửi 30 phóng viên nhưng không ai đăng. Lý do nhiều khả năng nhất là gì?',
    options:[{k:'a',t:'Gửi quá ít phóng viên, cần gửi vài trăm địa chỉ mới có người đăng'},{k:'b',t:'Mộc An chưa chi tiền quảng cáo với các tòa soạn đó nên bị lờ đi'},
             {k:'c',t:'Bản tin không có gì mới hay đáng đọc với độc giả của họ'},{k:'d',t:'Gửi sai ngày trong tuần, phóng viên bận nên chưa kịp đọc'}],
    answer:'c', why:{a:'Gửi nhiều hơn một nội dung không có tin chỉ nhân số người bỏ qua.',
      b:'Quan hệ quảng cáo có thể giúp bài trả tiền, nhưng bài tin tự nhiên vẫn cần giá trị tin tức.',
      c:'Đúng. "Chất lượng cao, thơm ngon" là lời tự khen, không có yếu tố mới, con người hay con số.',
      d:'Thời điểm có ảnh hưởng, nhưng không giải thích việc cả 30 người đều không đăng.'} },
  { type:'mcq', stem:'Bạn phụ trách PR của Mộc An, được chọn một góc để gửi lại báo chí. Bạn chọn góc nào?',
    options:[{k:'a',t:'Sữa óc chó mới có công thức ít đường hơn dòng cũ 20%'},{k:'b',t:'120 hộ Lào Cai bán óc chó cho Mộc An cao hơn giá thương lái 15%'},
             {k:'c',t:'Mộc An là thương hiệu sữa hạt được yêu thích nhất theo khảo sát nội bộ'},{k:'d',t:'Giám đốc Mộc An chia sẻ tầm nhìn trở thành số một ngành sữa hạt'}],
    answer:'b', why:{a:'Có con số nhưng vẫn là tính năng sản phẩm; hợp với quảng cáo hơn là tin.',
      b:'Đúng. Có con người, có thay đổi, có con số kiểm chứng được — và sản phẩm đi kèm tự nhiên.',
      c:'Khảo sát nội bộ tự khen không kiểm chứng được, nhà báo sẽ nghi ngờ ngay.',
      d:'Tầm nhìn của giám đốc chỉ thành tin khi giám đốc đã là người độc giả quan tâm.'} },
  { type:'calc', stem:'Mộc An gửi góc mới cho 30 phóng viên, có 6 bài đăng. Tỉ lệ đăng bài là bao nhiêu phần trăm?',
    unit:'%', ans:20, tol:0.1, wrong:[[500,'SAI_MAU_SO'],[5,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ đăng = số bài đăng ÷ số phóng viên nhận.','6 ÷ 30 = 0,2 = <b>20%</b>.'] },
  { type:'mcq', stem:'Yếu tố nào sau đây KHÔNG làm tăng giá trị tin tức của một câu chuyện doanh nghiệp?',
    options:[{k:'a',t:'Một nhân vật cụ thể có câu chuyện riêng, có tên và ảnh'},{k:'b',t:'Một con số kiểm chứng được, so với mốc trước đó'},
             {k:'c',t:'Một thay đổi lần đầu xảy ra trong ngành tại Việt Nam'},{k:'d',t:'Thêm các tính từ như "đột phá", "tiên phong", "hàng đầu"'}],
    answer:'d', why:{a:'Nhân vật là yếu tố con người — thứ khiến độc giả đọc tiếp.',
      b:'Con số cụ thể giúp nhà báo kiểm chứng và làm tít.',
      c:'"Lần đầu" là yếu tố mới, một trong những lý do mạnh nhất để đăng.',
      d:'Đúng. Tính từ tự khen làm bản tin giống quảng cáo hơn, nhà báo thường xoá sạch.'} },
  { type:'mcq', stem:'Một chuỗi cà phê hư cấu mở quán thứ 50. Góc nào dễ thành tin nhất với báo địa phương Đà Nẵng?',
    options:[{k:'a',t:'Chuỗi đạt cột mốc 50 quán trên toàn quốc, gửi lời cảm ơn tới khách hàng cả nước'},{k:'b',t:'Quán thứ 50 ở Đà Nẵng tuyển 12 người khiếm thính làm pha chế'},
             {k:'c',t:'Menu quán mới có thêm ba món đồ uống theo mùa hè'},{k:'d',t:'Chuỗi giảm giá 50% trong ngày khai trương để tri ân'}],
    answer:'b', why:{a:'Cột mốc của doanh nghiệp ít liên quan tới độc giả Đà Nẵng.',
      b:'Đúng. Gần (tại Đà Nẵng), con người, khác thường — đủ ba yếu tố.',
      c:'Món mới là thông tin bán hàng, hợp với fanpage hơn là báo.',
      d:'Khuyến mãi là quảng cáo; báo sẽ bảo bạn mua chỗ quảng cáo.'} },
  { type:'mcq', stem:'Vì sao người làm PR nên đi "đào" ở các phòng ban như R&D, thu mua, nhân sự?',
    options:[{k:'a',t:'Để có thêm trưởng phòng cùng ký tên trên thông cáo, giúp bản tin có trọng lượng hơn với tòa soạn'},{k:'b',t:'Để chia bớt việc viết bài cho các phòng ban khác làm thay'},
             {k:'c',t:'Vì phòng marketing thường không được phép phát ngôn với báo'},{k:'d',t:'Vì câu chuyện có tin thường nằm ở vận hành, không ở tờ giới thiệu sản phẩm'}],
    answer:'d', why:{a:'Chữ ký nhiều không làm câu chuyện đáng đọc hơn.',
      b:'Các phòng ban cung cấp chất liệu, còn việc biến nó thành tin vẫn là của PR.',
      c:'Quy định phát ngôn tuỳ công ty; đó không phải lý do để đi tìm chuyện.',
      d:'Đúng. Thu mua, con người, quy trình mới là nơi có nhân vật, con số và thay đổi.'} },
  { type:'mcq', stem:'Sau khi bài về 120 hộ Lào Cai được đăng, sếp hỏi: "Sao báo nhắc sản phẩm ít quá?" Trả lời nào hợp lý nhất?',
    options:[{k:'a',t:'Nhắc ít là đúng cách: độc giả tin bài hơn, thương hiệu gắn với câu chuyện tốt'},{k:'b',t:'Lần sau sẽ yêu cầu phóng viên nhắc tên sản phẩm ngay ở tít và đoạn đầu, đổi lại hỗ trợ ảnh'},
             {k:'c',t:'Do phóng viên không thích sản phẩm nên cố tình nhắc ít lại'},{k:'d',t:'Nên chuyển sang bài trả tiền để kiểm soát toàn bộ nội dung bài'}],
    answer:'a', why:{a:'Đúng. Giá trị của bài tin tự nhiên là độ tin cậy; nhồi sản phẩm vào sẽ mất chính giá trị đó.',
      b:'Ép nhà báo nhắc sản phẩm ở tít là cách nhanh nhất để không được đăng lần sau.',
      c:'Nhắc ít là quy ước viết tin, không phải thái độ cá nhân của phóng viên.',
      d:'Bài trả tiền có chỗ dùng, nhưng người đọc nhận ra và tin ít hơn.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kn09-02', skill:'comm', read:'7 phút', t:'Thông cáo báo chí nào được nhà báo đọc hết?',
  situation:'Công ty ví điện tử hư cấu PayNhanh gửi thông cáo dài 4 trang. Ba đoạn đầu kể lịch sử công ty và cảm ơn đối tác; thông tin chính — 200.000 tiểu thương chợ truyền thống đã nhận thanh toán QR, doanh thu trung bình tăng 18% — nằm ở trang 3. Một phóng viên trả lời: "Tôi đọc ba dòng rồi xoá, vì không thấy tin."',
  concept:{ name:'Kim tự tháp ngược',
    body:'Nhà báo nhận hàng chục thông cáo mỗi ngày và quyết định trong vài giây. Thông cáo tốt viết theo <b>kim tự tháp ngược</b>: tít nêu tin; đoạn đầu trả lời ai, làm gì, khi nào, ở đâu, vì sao, con số chính; đoạn sau là chi tiết, trích dẫn; cuối cùng mới là giới thiệu công ty. Kèm theo: một trích dẫn người thật nói như người thật, ảnh dùng được, đầu mối liên hệ trả lời nhanh. Độ dài tốt thường gói trong một trang. Nhà báo cắt từ dưới lên — phần quan trọng phải nằm trên cùng.' },
  example:'PayNhanh viết lại: tít "200.000 tiểu thương chợ nhận thanh toán QR, doanh thu tăng 18%". Đoạn đầu nói rõ phạm vi 12 tỉnh, trong 9 tháng. Tiếp theo là trích lời một bà bán rau ở chợ Bà Chiểu. Lịch sử công ty rút còn ba dòng cuối. Bản mới dài 1 trang thay vì 4. Gửi 40 phóng viên, 10 người hồi âm hỏi thêm — so với 1 người ở bản cũ.',
  takeaway:'Tin nằm ở tít và đoạn đầu; phần giới thiệu công ty để cuối cùng, vì nhà báo cắt từ dưới lên.',
  apply:'Lấy một thông cáo bất kỳ trên website một doanh nghiệp. Trong 60 giây, nói tin chính là gì và nó nằm ở dòng thứ mấy.',
  mistakes:['Mở đầu thông cáo bằng lịch sử, tầm nhìn và lời cảm ơn.','Trích dẫn lãnh đạo bằng câu sáo rỗng không ai nói ngoài đời.'],
  q:[
  { type:'mcq', stem:'Thông cáo 4 trang của PayNhanh bị xoá sau ba dòng. Vấn đề chính nằm ở đâu?',
    options:[{k:'a',t:'Thông cáo chưa đủ số liệu tài chính, nhà báo không có gì để viết thành bài'},{k:'b',t:'Tin chính bị chôn ở trang 3, ba dòng đầu không có gì mới'},
             {k:'c',t:'Ví điện tử là ngành báo chí không bao giờ quan tâm'},{k:'d',t:'Thiếu logo và màu thương hiệu ở đầu trang thông cáo'}],
    answer:'b', why:{a:'Bốn trang là dài, không phải ngắn.',
      b:'Đúng. Nhà báo quyết định trong vài dòng; tin không ở đó thì thông cáo bị bỏ.',
      c:'Con số 200.000 tiểu thương là tin tốt, ngành nào cũng có thể lên báo.',
      d:'Hình thức không cứu được một thông cáo không có tin ở đầu.'} },
  { type:'mcq', stem:'Bạn viết lại thông cáo PayNhanh. Đoạn đầu tiên bạn đặt gì?',
    options:[{k:'a',t:'Lời cảm ơn đối tác, ngân hàng liên kết và cơ quan quản lý đã đồng hành suốt chặng đường'},{k:'b',t:'Tầm nhìn trở thành ví điện tử của mọi người Việt vào năm 2030'},
             {k:'c',t:'200.000 tiểu thương ở 12 tỉnh nhận QR trong 9 tháng, doanh thu tăng 18%'},{k:'d',t:'Lịch sử thành lập và các giải thưởng công ty đã nhận được'}],
    answer:'c', why:{a:'Lời cảm ơn là phép lịch sự, nên để phần cuối nếu cần.',
      b:'Tầm nhìn là mong muốn, chưa phải sự kiện đã xảy ra.',
      c:'Đúng. Ai, làm gì, ở đâu, bao lâu, con số — đủ để nhà báo quyết định ngay.',
      d:'Lịch sử công ty là phần nhà báo cắt đầu tiên.'} },
  { type:'calc', stem:'Bản cũ gửi 40 phóng viên có 1 hồi âm; bản mới gửi 40 phóng viên có 10 hồi âm. Tỉ lệ hồi âm của bản mới là bao nhiêu phần trăm?',
    unit:'%', ans:25, tol:0.1, wrong:[[400,'SAI_MAU_SO'],[22.5,'NHAM_DIEM_PHAN_TRAM']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ hồi âm = số hồi âm ÷ số phóng viên nhận.','10 ÷ 40 = 0,25 = <b>25%</b> (bản cũ chỉ 2,5%).'] },
  { type:'mcq', stem:'Trích dẫn nào của lãnh đạo PayNhanh dễ được nhà báo giữ lại trong bài nhất?',
    options:[{k:'a',t:'"Chúng tôi luôn đặt khách hàng làm trung tâm trong mọi hoạt động"'},{k:'b',t:'"Đây là bước tiến quan trọng trên hành trình phát triển bền vững"'},
             {k:'c',t:'"Chúng tôi tự hào mang đến giải pháp thanh toán tiên phong"'},{k:'d',t:'"Nhiều cô bán rau trước giờ mất khách vì không có tiền lẻ để thối"'}],
    answer:'d', why:{a:'Câu này công ty nào cũng nói được, nên nhà báo bỏ.',
      b:'Sáo rỗng, không có chi tiết nào mới.',
      c:'Tự khen, không cho độc giả thêm hiểu biết gì.',
      d:'Đúng. Cụ thể, có hình ảnh, nói như người thật — thêm được vào bài.'} },
  { type:'mcq', stem:'Vì sao phần giới thiệu công ty nên nằm cuối thông cáo?',
    options:[{k:'a',t:'Vì nhà báo cắt bài từ dưới lên, phần cuối là phần ít quan trọng nhất'},{k:'b',t:'Vì theo quy định, mọi văn bản doanh nghiệp gửi báo chí phải đặt phần này ở cuối trang'},
             {k:'c',t:'Vì phần này dài nhất nên đặt cuối cho gọn mắt người đọc'},{k:'d',t:'Vì độc giả thích đọc về công ty sau khi đã đọc xong bài'}],
    answer:'a', why:{a:'Đúng. Kim tự tháp ngược xếp thông tin theo độ quan trọng giảm dần.',
      b:'Đây là quy ước nghề, không phải quy định bắt buộc.',
      c:'Độ dài không phải lý do; phần này nên ngắn.',
      d:'Độc giả hiếm khi đọc tới phần giới thiệu công ty.'} },
  { type:'mcq', stem:'Một hãng mỹ phẩm hư cấu gửi thông cáo nhưng đầu mối liên hệ ghi email chung "info@", trả lời sau 3 ngày. Hậu quả dễ xảy ra nhất?',
    options:[{k:'a',t:'Nhà báo sẽ gọi thẳng tổng đài chăm sóc khách hàng để hỏi thêm và trích lời nhân viên trực'},{k:'b',t:'Không sao, vì nội dung thông cáo đã đầy đủ để tự viết bài'},
             {k:'c',t:'Nhà báo cần xác minh gấp, không liên lạc được nên bỏ bài hoặc viết thiếu'},{k:'d',t:'Báo sẽ tự dùng ảnh trên mạng xã hội của hãng để minh hoạ'}],
    answer:'c', why:{a:'Tổng đài thường không có thẩm quyền trả lời báo chí.',
      b:'Nhà báo gần như luôn cần hỏi thêm hoặc xác minh trước khi đăng.',
      c:'Đúng. Tin có hạn; đầu mối chậm biến thông cáo tốt thành bài không đăng.',
      d:'Chuyện ảnh là phụ; vấn đề chính là không xác minh được thông tin.'} },
  { type:'mcq', stem:'Tít nào tốt nhất cho thông cáo của PayNhanh?',
    options:[{k:'a',t:'PayNhanh tiếp tục khẳng định vị thế trên thị trường thanh toán'},{k:'b',t:'200.000 tiểu thương chợ nhận QR, doanh thu tăng 18% sau 9 tháng'},
             {k:'c',t:'PayNhanh: hành trình số hoá đầy cảm hứng cùng chợ truyền thống'},{k:'d',t:'Thông cáo báo chí về kết quả hoạt động quý III của PayNhanh'}],
    answer:'b', why:{a:'"Khẳng định vị thế" không nói điều gì đã xảy ra.',
      b:'Đúng. Tít là tin: ai, làm gì, con số, thời gian.',
      c:'Cảm xúc chung chung, nhà báo không lấy làm tít được.',
      d:'Tít hành chính, không có tin nào trong đó.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kn09-03', skill:'comm', read:'6 phút', t:'Chỉ gọi nhà báo khi cần đăng bài thì sao?',
  situation:'Chị Lan, PR của chuỗi nhà thuốc hư cấu An Khang Plus, chỉ liên lạc với phóng viên khi có sự kiện ra mắt — khoảng 2 lần mỗi năm. Khi chuỗi bị một bài báo phản ánh sai giá thuốc, chị gọi 8 phóng viên quen để đính chính, chỉ 1 người nghe máy. Đồng nghiệp ở công ty khác thì gặp phóng viên mỗi tháng dù không có gì cần đăng.',
  concept:{ name:'Quan hệ báo chí là quan hệ nguồn tin',
    body:'Nhà báo cần <b>nguồn tin đáng tin</b>: người trả lời nhanh, số liệu đúng, giải thích ngành giúp họ viết tốt hơn — kể cả khi bài không nhắc tới công ty bạn. Quan hệ được xây trong lúc bình yên và được dùng trong lúc khó khăn. Cách làm: biết mỗi phóng viên theo mảng gì; gửi đúng thứ họ cần, không gửi hàng loạt; nhận lời phỏng vấn cả khi chủ đề không có lợi trực tiếp; không bao giờ nói sai và không đòi xem bài trước khi đăng. Tặng quà hay "phong bì" không tạo quan hệ nguồn tin — chỉ tạo rủi ro.' },
  example:'Trong một năm, đồng nghiệp của chị Lan trả lời 12 câu hỏi của phóng viên về giá thuốc, thiếu thuốc, cách đọc hoá đơn — không câu nào quảng cáo cho công ty. Khi công ty anh bị phản ánh sai, 5 trên 6 phóng viên gọi lại anh để hỏi phía công ty trước khi viết tiếp. Chị Lan có 8 số điện thoại nhưng không có một quan hệ nào.',
  takeaway:'Hãy làm nguồn tin đáng tin trong lúc yên ổn; khi khủng hoảng tới, nhà báo sẽ gọi bạn trước.',
  apply:'Liệt kê 3 phóng viên theo mảng ngành của bạn. Trong 60 giây, nói với mỗi người một thông tin hữu ích bạn có thể cho họ mà không nhắc tới sản phẩm.',
  mistakes:['Chỉ gọi nhà báo khi cần đăng bài hoặc cần gỡ bài.','Đòi xem trước bài viết hoặc sửa câu chữ của nhà báo.'],
  q:[
  { type:'mcq', stem:'Vì sao khi cần đính chính, chị Lan gọi 8 phóng viên nhưng chỉ 1 người nghe máy?',
    options:[{k:'a',t:'Vì phóng viên thường không nghe máy số lạ trong giờ làm việc và giờ chạy tin buổi chiều'},{k:'b',t:'Vì chị chưa gửi quà dịp lễ Tết nên phóng viên phật lòng'},
             {k:'c',t:'Vì ngành dược là ngành báo chí thích đưa tin xấu hơn'},{k:'d',t:'Vì chị chỉ liên lạc khi cần, chưa từng là nguồn tin hữu ích với họ'}],
    answer:'d', why:{a:'Họ có số chị; vấn đề là họ không thấy lý do ưu tiên.',
      b:'Quà không tạo được lòng tin nghề nghiệp, và còn tạo rủi ro.',
      c:'Không có cơ sở; vấn đề nằm ở quan hệ chứ không ở ngành.',
      d:'Đúng. Quan hệ một chiều thì lúc khó không có ai đứng về phía mình để hỏi lại.'} },
  { type:'mcq', stem:'Một phóng viên hỏi bạn giải thích vì sao giá một nhóm thuốc tăng, bài không nhắc tới công ty bạn. Bạn làm gì?',
    options:[{k:'a',t:'Từ chối lịch sự, vì bài không mang lại lợi ích gì cho công ty'},{k:'b',t:'Nhận lời nếu phóng viên hứa nhắc tên công ty trong bài'},
             {k:'c',t:'Trả lời nhanh, đúng số liệu, dù bài không nhắc tên công ty'},{k:'d',t:'Chuyển câu hỏi cho phòng pháp chế xử lý trong vài tuần tới'}],
    answer:'c', why:{a:'Đây chính là lúc xây vị trí nguồn tin, bỏ qua là mất cơ hội.',
      b:'Mặc cả điều kiện làm bạn thành người đi quảng cáo, không phải nguồn tin.',
      c:'Đúng. Giúp nhà báo viết tốt hơn là khoản gửi vào "tài khoản lòng tin".',
      d:'Nhà báo có hạn chót; trả lời sau vài tuần là không trả lời.'} },
  { type:'calc', stem:'Khi công ty bị phản ánh sai, đồng nghiệp của chị Lan có 5 trên 6 phóng viên gọi lại hỏi phía công ty. Tỉ lệ đó là bao nhiêu phần trăm (làm tròn 1 chữ số thập phân)?',
    unit:'%', ans:83.3, tol:0.2, wrong:[[120,'SAI_MAU_SO'],[62.5,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = số phóng viên gọi lại ÷ số phóng viên theo dõi vụ việc.','5 ÷ 6 ≈ 0,833 = <b>83,3%</b>.'] },
  { type:'mcq', stem:'Việc nào làm hỏng quan hệ với nhà báo nhanh nhất?',
    options:[{k:'a',t:'Đưa số liệu sai để bài có lợi hơn cho công ty mình'},{k:'b',t:'Từ chối trả lời một câu hỏi vì chưa có thông tin chính thức'},
             {k:'c',t:'Gửi thông tin theo đúng mảng mà phóng viên đang theo dõi'},{k:'d',t:'Hẹn cà phê khi không có thông cáo nào cần phải gửi'}],
    answer:'a', why:{a:'Đúng. Nhà báo đăng sai vì bạn là mất uy tín của họ — họ sẽ không tin bạn nữa.',
      b:'Nói thật là chưa có thông tin vẫn giữ được lòng tin.',
      c:'Đây là cách làm đúng, giúp quan hệ tốt hơn.',
      d:'Gặp khi không cần gì là cách xây quan hệ lâu dài.'} },
  { type:'mcq', stem:'Sếp muốn bạn yêu cầu phóng viên gửi bài để duyệt trước khi đăng. Bạn giải thích thế nào?',
    options:[{k:'a',t:'Đồng ý, vì công ty có quyền kiểm soát mọi thông tin nhắc tới tên và sản phẩm của mình trên báo'},{k:'b',t:'Đồng ý nhưng chỉ duyệt phần trích dẫn và tên sản phẩm trong bài'},
             {k:'c',t:'Bài tin là của tòa soạn; đòi duyệt làm mất lòng tin, chỉ nên kiểm tra số liệu'},{k:'d',t:'Hãy trả tiền cho bài viết thì sẽ được duyệt toàn bộ nội dung'}],
    answer:'c', why:{a:'Bài tin không phải tài sản của công ty; đòi kiểm soát sẽ làm phóng viên tránh bạn.',
      b:'Ngay cả việc đòi duyệt trích dẫn cũng dễ bị coi là can thiệp.',
      c:'Đúng. Có thể đề nghị kiểm tra số liệu kỹ thuật, không đòi sửa câu chữ.',
      d:'Bài trả tiền là quảng cáo, không thay được bài tin độc lập.'} },
  { type:'mcq', stem:'Một hãng bia hư cấu gửi cùng một thông cáo cho 300 địa chỉ, gồm cả phóng viên thể thao và y tế. Vấn đề là gì?',
    options:[{k:'a',t:'300 địa chỉ là quá ít để có hiệu quả cho một thương hiệu bia lớn'},{k:'b',t:'Gửi sai mảng làm phiền nhà báo và khiến email sau dễ bị bỏ qua'},
             {k:'c',t:'Phóng viên y tế sẽ viết bài tấn công hãng bia vì thông cáo này'},{k:'d',t:'Không vấn đề gì, vì ai không cần thì họ tự xoá đi thôi'}],
    answer:'b', why:{a:'Số lượng không phải vấn đề; sai người nhận mới là vấn đề.',
      b:'Đúng. Gửi hàng loạt không chọn lọc là cách nhanh nhất để thành "thư rác".',
      c:'Kết luận quá xa; điều thường xảy ra là họ bỏ qua bạn.',
      d:'Mỗi lần gửi sai là bào mòn lòng tin cho những lần gửi sau.'} },
  { type:'mcq', stem:'Cách nào giúp bạn biết phóng viên nào nên nhận thông tin gì?',
    options:[{k:'a',t:'Mua danh sách email báo chí và gửi đều cho tất cả'},{k:'b',t:'Hỏi tổng biên tập xem ai cần thông tin của công ty mình'},
             {k:'c',t:'Chỉ theo dõi các phóng viên có lượng người theo dõi lớn nhất'},{k:'d',t:'Đọc bài họ viết gần đây, ghi lại mảng và góc họ hay viết'}],
    answer:'d', why:{a:'Danh sách mua sẵn không cho biết ai quan tâm điều gì.',
      b:'Tổng biên tập không làm việc điều phối thông cáo cho doanh nghiệp.',
      c:'Độ nổi tiếng không nói lên họ có theo mảng của bạn không.',
      d:'Đúng. Đọc bài của họ là cách chính xác nhất để gửi đúng thứ họ cần.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kn09-04', skill:'channel', read:'7 phút', t:'Tài trợ giải chạy 500 triệu đổi lấy gì?',
  situation:'Hãng nước điện giải hư cấu Sóng Xanh được mời tài trợ chính giải chạy bộ 10.000 người ở Quy Nhơn, giá 500 triệu. Gói gồm logo trên áo, băng rôn, gian hàng. Nhóm marketing chia hai phe: một phe muốn logo to nhất có thể; phe kia muốn dùng tiền để phát nước tại các trạm tiếp nước và làm câu chuyện với người chạy.',
  concept:{ name:'Tài trợ phải được "kích hoạt"',
    body:'Logo trên băng rôn chỉ mua được <b>sự hiện diện</b>. Một tài trợ có ích khi thương hiệu đóng vai trò có thật trong sự kiện, liên quan tới lợi ích sản phẩm — gọi là <b>kích hoạt</b> tài trợ. Nhiều người làm nghề để thêm một khoản ngân sách kích hoạt riêng, có khi bằng hoặc hơn phí tài trợ. Đánh giá tài trợ bằng ba câu: người tham dự có dùng thử sản phẩm không; có câu chuyện nào để báo chí và mạng xã hội kể lại không; và chi phí trên mỗi người tiếp cận thật là bao nhiêu.' },
  example:'Sóng Xanh trả 500 triệu phí tài trợ và thêm 300 triệu kích hoạt: 12 trạm nước điện giải, đo mất nước miễn phí cho người chạy trước và sau đua. 8.000 người uống thử. Báo địa phương đăng bài "Trạm nước giúp 40 người chạy tránh chuột rút". Tổng 800 triệu cho 8.000 người dùng thử thật — 100 nghìn đồng mỗi người, tốn nhưng có lý do để tính tiếp.',
  takeaway:'Logo mua sự hiện diện; kích hoạt mới mua trải nghiệm và câu chuyện — hãy ngân sách cho cả hai.',
  apply:'Chọn một sự kiện ở địa phương bạn. Trong 60 giây, nói thương hiệu nào hợp tài trợ và vai trò thật mà nó có thể đóng.',
  mistakes:['Trả phí tài trợ rồi không còn tiền để kích hoạt.','Đo tài trợ bằng số lần logo xuất hiện thay vì số người dùng thử.'],
  q:[
  { type:'mcq', stem:'Với 500 triệu tài trợ giải chạy, cách dùng nào có khả năng mang lại nhiều nhất cho Sóng Xanh?',
    options:[{k:'a',t:'Logo to nhất trên áo và băng rôn ở vạch đích, để mọi bức ảnh về đích đều có thương hiệu'},{k:'b',t:'Phát nước điện giải tại trạm tiếp nước, gắn với nhu cầu thật'},
             {k:'c',t:'Mời một ca sĩ nổi tiếng lên sân khấu khai mạc giải chạy'},{k:'d',t:'In logo lên huy chương để người chạy giữ lại làm kỷ niệm'}],
    answer:'b', why:{a:'Hiện diện có ích nhưng không cho ai nếm thử sản phẩm.',
      b:'Đúng. Sản phẩm đóng vai trò có thật đúng lúc người chạy cần nó.',
      c:'Ca sĩ thu hút sự chú ý cho ca sĩ, không cho lợi ích sản phẩm.',
      d:'Huy chương là kỷ niệm của giải, ít người nhớ nhà tài trợ in trên đó.'} },
  { type:'mcq', stem:'Bạn được duyệt tổng 800 triệu cho giải chạy. Bạn chọn cách chia nào?',
    options:[{k:'a',t:'800 triệu cho phí tài trợ để lên hạng kim cương, logo to nhất'},{k:'b',t:'700 triệu phí tài trợ, 100 triệu in thêm băng rôn dọc đường chạy'},
             {k:'c',t:'Toàn bộ cho quảng cáo mạng xã hội quanh giải, không tài trợ'},{k:'d',t:'500 triệu phí tài trợ, 300 triệu làm trạm nước và đo mất nước'}],
    answer:'d', why:{a:'Hạng cao hơn chỉ cho thêm hiện diện, không thêm trải nghiệm.',
      b:'Băng rôn thêm vẫn là hiện diện, không có người dùng thử.',
      c:'Mất quyền có mặt tại sự kiện — nơi người chạy thật sự cần sản phẩm.',
      d:'Đúng. Phí mua quyền có mặt, ngân sách kích hoạt biến quyền đó thành trải nghiệm.'} },
  { type:'calc', stem:'Sóng Xanh chi 500 triệu phí tài trợ và 300 triệu kích hoạt, có 8.000 người uống thử. Chi phí trên mỗi người dùng thử là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:100, tol:0.5, wrong:[[62.5,'QUEN_CHI_PHI_CO_DINH'],[80,'SAI_MAU_SO']], errors:['QUEN_CHI_PHI_CO_DINH','SAI_MAU_SO'],
    steps:['Tổng chi = 500 + 300 = 800 triệu.','800.000.000 ÷ 8.000 = 100.000đ = <b>100 nghìn đồng</b> mỗi người.'] },
  { type:'mcq', stem:'Một ngân hàng hư cấu tài trợ lễ hội ẩm thực. Hoạt động kích hoạt nào hợp nhất?',
    options:[{k:'a',t:'Treo logo ngân hàng thật to ở cổng chính của lễ hội'},{k:'b',t:'Phát tờ rơi mở thẻ tín dụng tại mọi lối vào lễ hội'},
             {k:'c',t:'Thanh toán QR tại mọi gian hàng, giảm 20% khi trả bằng ứng dụng'},{k:'d',t:'Tổ chức hội thảo về tài chính cá nhân và tiết kiệm cho gia đình ngay trong lễ hội'}],
    answer:'c', why:{a:'Chỉ là hiện diện, không ai trải nghiệm dịch vụ.',
      b:'Tờ rơi ép bán, không giải quyết nhu cầu nào ở lễ hội.',
      c:'Đúng. Ngân hàng giải quyết việc thanh toán — nhu cầu thật trong lễ hội.',
      d:'Hội thảo lạc chỗ; người tới lễ hội để ăn, không để học tài chính.'} },
  { type:'mcq', stem:'Vì sao nên có ngân sách kích hoạt riêng ngoài phí tài trợ?',
    options:[{k:'a',t:'Vì phí tài trợ chỉ mua quyền có mặt; biến nó thành trải nghiệm cần thêm tiền'},{k:'b',t:'Vì ban tổ chức luôn yêu cầu nhà tài trợ chi thêm khoản đó'},
             {k:'c',t:'Vì khoản kích hoạt được tính là chi phí hoạt động xã hội nên doanh nghiệp được giảm thuế'},{k:'d',t:'Vì phí tài trợ thường bị hoàn lại nếu không kích hoạt'}],
    answer:'a', why:{a:'Đúng. Quyền có mặt không tự tạo ra người dùng thử hay câu chuyện.',
      b:'Ban tổ chức không bắt buộc; nhiều nhà tài trợ chỉ trả phí.',
      c:'Không nên đưa ra kết luận thuế như một lý do marketing.',
      d:'Phí tài trợ không hoàn lại vì bạn không kích hoạt.'} },
  { type:'mcq', stem:'Chỉ số nào nói nhiều nhất về hiệu quả của một tài trợ có kích hoạt?',
    options:[{k:'a',t:'Số lần logo xuất hiện trong ảnh chụp và video của sự kiện'},{k:'b',t:'Số người dùng thử và chi phí trên mỗi người dùng thử thật'},
             {k:'c',t:'Tổng số khách tới sự kiện theo báo cáo của ban tổ chức'},{k:'d',t:'Số bài báo nhắc tên sự kiện, kể cả không nhắc thương hiệu'}],
    answer:'b', why:{a:'Đếm logo đo hiện diện, không đo trải nghiệm.',
      b:'Đúng. Người dùng thử là kết quả mà kích hoạt được thiết kế để tạo ra.',
      c:'Khách tới sự kiện chưa chắc đã tiếp xúc với thương hiệu.',
      d:'Bài không nhắc thương hiệu thì gần như không có giá trị cho nhà tài trợ.'} },
  { type:'mcq', stem:'Sự kiện nào kém hợp nhất để một hãng nước điện giải tài trợ?',
    options:[{k:'a',t:'Giải bóng đá phong trào công nhân ngày hè nóng'},{k:'b',t:'Giải đạp xe đường dài qua đèo Hải Vân'},
             {k:'c',t:'Ngày hội sách thiếu nhi trong nhà có điều hoà'},{k:'d',t:'Lễ hội leo núi Bà Đen vào tháng Giêng'}],
    answer:'c', why:{a:'Vận động nặng dưới nắng — sản phẩm có vai trò rõ.',
      b:'Người đạp đường dài mất nước, rất hợp phát sản phẩm.',
      c:'Đúng. Không có mất nước, sản phẩm không có vai trò thật để đóng.',
      d:'Leo núi đông người, ra mồ hôi — có nhu cầu bù nước.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kn09-05', skill:'comm', read:'6 phút', t:'Đây là khủng hoảng loại gì?',
  situation:'Trong cùng một tuần, ba thương hiệu hư cấu gặp chuyện. Hãng bánh Hạt Vàng có lô bánh bị khách phát hiện dị vật. Chuỗi gym FitGo có quản lý chi nhánh đăng bài chê người béo trên trang cá nhân. Hãng giao đồ ăn ShipSớm bị hàng trăm khách phàn nàn đơn trễ 2 tiếng trong đợt mưa lớn. Cả ba đều muốn "ra thông cáo xin lỗi" giống nhau.',
  concept:{ name:'Ba loại khủng hoảng thường gặp',
    body:'Mỗi loại khủng hoảng cần một phản ứng khác. <b>Khủng hoảng sản phẩm</b> (an toàn, chất lượng) đụng tới sức khoẻ: ưu tiên số một là hành động — ngừng bán, thu hồi, kiểm tra — trước lời nói. <b>Khủng hoảng phát ngôn</b> (một người nói sai) đụng tới giá trị: cần làm rõ công ty đứng ở đâu và xử lý người nói ra sao. <b>Khủng hoảng dịch vụ</b> (trễ, lỗi hàng loạt) đụng tới lời hứa: cần giải thích nguyên nhân, bồi hoàn và cách không lặp lại. Phân loại đúng giúp chọn đúng người phát ngôn và đúng hành động đi kèm.' },
  example:'Hạt Vàng: tạm ngừng bán lô bánh, công bố mã lô, mời khách đổi trả — do giám đốc chất lượng nói. FitGo: tạm đình chỉ quản lý, nói rõ quan điểm tôn trọng mọi vóc dáng — do giám đốc điều hành nói. ShipSớm: xin lỗi, tặng mã 30.000đ cho đơn trễ trên 60 phút, công bố phương án tăng tài xế ngày mưa — do giám đốc vận hành nói. Ba câu chuyện, ba cách làm.',
  takeaway:'Phân loại trước khi phản hồi: sản phẩm cần hành động, phát ngôn cần lập trường, dịch vụ cần bồi hoàn.',
  apply:'Nhớ một khủng hoảng bạn từng thấy trên mạng. Trong 60 giây, phân loại nó và nói hành động đầu tiên đúng là gì.',
  mistakes:['Dùng một mẫu thông cáo xin lỗi cho mọi loại khủng hoảng.','Chỉ nói lời xin lỗi khi khủng hoảng sản phẩm cần hành động thu hồi ngay.'],
  q:[
  { type:'mcq', stem:'Vì sao ba thương hiệu không nên dùng chung một mẫu thông cáo xin lỗi?',
    options:[{k:'a',t:'Vì thông cáo giống nhau sẽ bị báo chí phát hiện là sao chép'},{k:'b',t:'Vì mỗi loại khủng hoảng đụng tới thứ khác nhau và cần hành động khác'},
             {k:'c',t:'Vì chỉ thương hiệu có nhiều khách nhất trong ba mới cần xin lỗi công khai trên báo chí'},{k:'d',t:'Vì khủng hoảng dịch vụ thì không bao giờ cần xin lỗi'}],
    answer:'b', why:{a:'Chuyện sao chép là phụ; vấn đề là nội dung không khớp vấn đề.',
      b:'Đúng. An toàn, giá trị, lời hứa — mỗi thứ cần một phản ứng riêng.',
      c:'Quy mô không quyết định có cần xin lỗi hay không.',
      d:'Dịch vụ lỗi hàng loạt vẫn cần xin lỗi, kèm bồi hoàn.'} },
  { type:'mcq', stem:'Bạn phụ trách truyền thông của Hạt Vàng. Việc đầu tiên bạn đề xuất là gì?',
    options:[{k:'a',t:'Đăng bài xin lỗi cảm động trên fanpage trong vòng một giờ'},{k:'b',t:'Liên hệ khách phát hiện để đề nghị bồi thường và xin gỡ bài'},
             {k:'c',t:'Chờ kết quả kiểm nghiệm đầy đủ rồi mới lên tiếng'},{k:'d',t:'Tạm ngừng bán lô bánh đó và công bố mã lô cho khách đổi trả'}],
    answer:'d', why:{a:'Lời xin lỗi không thay được hành động bảo vệ người đang cầm bánh.',
      b:'Xin gỡ bài bị coi là bịt miệng và làm khủng hoảng nặng hơn.',
      c:'Chờ đợi khi có rủi ro sức khoẻ là sai lầm lớn nhất.',
      d:'Đúng. Với khủng hoảng sản phẩm, hành động bảo vệ khách đi trước lời nói.'} },
  { type:'mcq', stem:'Quản lý FitGo đăng bài chê người béo. Đây là loại khủng hoảng nào?',
    options:[{k:'a',t:'Khủng hoảng phát ngôn, đụng tới giá trị của thương hiệu'},{k:'b',t:'Khủng hoảng sản phẩm, vì dịch vụ gym là sản phẩm chính'},
             {k:'c',t:'Khủng hoảng dịch vụ, vì quản lý là người cung cấp dịch vụ'},{k:'d',t:'Chuyện cá nhân trên trang riêng, không liên quan thương hiệu'}],
    answer:'a', why:{a:'Đúng. Một người đại diện nói điều trái giá trị — khách hỏi "công ty nghĩ gì?".',
      b:'Chất lượng tập luyện không bị ảnh hưởng; thứ bị đụng là giá trị.',
      c:'Không có lỗi phục vụ hàng loạt nào xảy ra.',
      d:'Khách không tách được quản lý chi nhánh khỏi thương hiệu.'} },
  { type:'calc', stem:'ShipSớm có 1.200 đơn trễ trên 60 phút, mỗi đơn được tặng mã 30.000đ. Nếu 70% khách dùng mã, chi phí bồi hoàn thực tế là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:25.2, tol:0.1, wrong:[[36,'QUEN_TI_LE_CHUYEN_DOI'],[10.8,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Số mã được dùng = 1.200 × 70% = 840 mã.','840 × 30.000 = 25.200.000đ = <b>25,2 triệu đồng</b>.'] },
  { type:'mcq', stem:'Ai nên là người phát ngôn chính cho khủng hoảng dịch vụ của ShipSớm?',
    options:[{k:'a',t:'Một người nổi tiếng từng quảng cáo cho ShipSớm'},{k:'b',t:'Nhân viên chăm sóc khách hàng trả lời từng bình luận của khách trên fanpage'},
             {k:'c',t:'Giám đốc vận hành — người nói được nguyên nhân và cách sửa'},{k:'d',t:'Luật sư của công ty để tránh rủi ro pháp lý'}],
    answer:'c', why:{a:'Người nổi tiếng không có thẩm quyền hay hiểu biết vận hành.',
      b:'CSKH cần phản hồi từng người, nhưng không thay được lời chính thức.',
      c:'Đúng. Khủng hoảng lời hứa cần người chịu trách nhiệm cho lời hứa đó.',
      d:'Luật sư hợp khi có tranh chấp, giọng pháp lý làm khách thấy lạnh lùng.'} },
  { type:'mcq', stem:'Một hãng nước mắm hư cấu bị phát hiện ghi sai độ đạm trên nhãn. Đây gần nhất với loại nào?',
    options:[{k:'a',t:'Khủng hoảng phát ngôn, vì nhãn là lời nói của hãng'},{k:'b',t:'Khủng hoảng dịch vụ, vì liên quan tới lời hứa với khách'},
             {k:'c',t:'Không phải khủng hoảng, vì sản phẩm vẫn ăn được bình thường'},{k:'d',t:'Khủng hoảng sản phẩm, vì chất lượng thật khác với cam kết'}],
    answer:'d', why:{a:'Nhãn là thông tin sản phẩm, không phải phát ngôn cá nhân.',
      b:'Dịch vụ là quá trình phục vụ; đây là chất lượng hàng hoá.',
      c:'Sai lệch chất lượng làm mất lòng tin dù không gây hại tức thì.',
      d:'Đúng. Cần hành động với sản phẩm: kiểm tra, sửa nhãn, xử lý hàng đang bán.'} },
  { type:'mcq', stem:'Với FitGo, câu nào nên có trong phản hồi chính thức?',
    options:[{k:'a',t:'"Đây là quan điểm cá nhân, không liên quan tới công ty"'},{k:'b',t:'"Chúng tôi đã tạm đình chỉ người quản lý và tôn trọng mọi vóc dáng"'},
             {k:'c',t:'"Rất tiếc nếu bài viết của một cá nhân đã làm một số người cảm thấy không vui"'},{k:'d',t:'"Chúng tôi sẽ kiện những tài khoản xuyên tạc sự việc"'}],
    answer:'b', why:{a:'Chối bỏ nghe như né tránh, khách vẫn thấy người đó đại diện công ty.',
      b:'Đúng. Có hành động xử lý và nêu rõ lập trường giá trị.',
      c:'"Rất tiếc nếu" đẩy lỗi sang cảm xúc người đọc.',
      d:'Đe doạ kiện làm công ty thành kẻ bắt nạt.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kn09-06', skill:'comm', read:'7 phút', t:'Giờ vàng đầu tiên: ai nói, nói gì?',
  situation:'21 giờ tối thứ Sáu, một video quay cảnh chuột chạy trong bếp một quán của chuỗi lẩu hư cấu Nồi Đỏ được chia sẻ nhanh. Sau 1 giờ có 3.000 lượt chia sẻ, sau 3 giờ có 18.000. Giám đốc muốn đợi sáng thứ Hai họp đủ ban lãnh đạo rồi mới ra thông báo. Trưởng phòng truyền thông lo rằng tới lúc đó câu chuyện đã được người khác kể thay.',
  concept:{ name:'Giờ vàng và thông điệp giữ chỗ',
    body:'Trong khủng hoảng, khoảng trống thông tin sẽ bị tin đồn lấp. Người làm nghề hay nói về <b>giờ vàng</b>: sớm nhất có thể, thường trong vài giờ đầu, công ty phải nói điều gì đó dù chưa biết hết. Đó là <b>thông điệp giữ chỗ</b> gồm ba ý: chúng tôi đã biết; đây là việc đang làm ngay (ví dụ tạm đóng quán để kiểm tra); khi nào sẽ có thông tin tiếp. Không đoán nguyên nhân, không đổ lỗi. Người phát ngôn là người có thẩm quyền quyết định hành động, và cả công ty chỉ nói một giọng.' },
  example:'Nồi Đỏ đăng lúc 22 giờ 30: "Chúng tôi đã thấy video tại quán Cầu Giấy. Quán tạm đóng từ tối nay để kiểm tra và khử trùng. Chúng tôi sẽ cập nhật trước 12 giờ trưa mai." Người ký: giám đốc điều hành. Sáng hôm sau, lượt chia sẻ mới mỗi giờ giảm dần, và phần lớn bài chia sẻ lại kèm luôn thông báo của Nồi Đỏ, thay vì chỉ có video.',
  takeaway:'Nói sớm điều bạn biết và điều đang làm; im lặng tới sáng thứ Hai là để người khác kể câu chuyện của bạn.',
  apply:'Viết trong 60 giây một thông điệp giữ chỗ ba câu cho một khủng hoảng giả định của công ty bạn.',
  mistakes:['Đợi biết đủ mọi thứ rồi mới lên tiếng.','Để nhiều người trong công ty nói nhiều phiên bản khác nhau.'],
  q:[
  { type:'mcq', stem:'Nếu Nồi Đỏ đợi tới sáng thứ Hai mới lên tiếng, điều gì dễ xảy ra nhất?',
    options:[{k:'a',t:'Câu chuyện tự lắng xuống qua cuối tuần vì mọi người bận đi chơi'},{k:'b',t:'Báo chí sẽ đợi tới thứ Hai để hỏi phía công ty rồi mới viết'},
             {k:'c',t:'Khoảng trống bị lấp bằng suy đoán, câu chuyện do người khác kể'},{k:'d',t:'Khách hàng sẽ đánh giá cao sự cẩn trọng khi công ty đợi đủ thông tin'}],
    answer:'c', why:{a:'Nội dung gây sốc thường lan mạnh hơn vào cuối tuần.',
      b:'Báo điện tử viết ngay, ghi "chưa liên lạc được với doanh nghiệp".',
      c:'Đúng. Im lặng hai ngày là hai ngày người khác định nghĩa sự việc.',
      d:'Khách không thấy "cẩn trọng", họ thấy im lặng như thể né tránh.'} },
  { type:'mcq', stem:'Bạn là trưởng phòng truyền thông của Nồi Đỏ lúc 22 giờ. Bạn đề xuất gì?',
    options:[{k:'a',t:'Đăng ngay một bài giải thích chuột có thể chạy từ công trình bên cạnh sang trong đêm'},{k:'b',t:'Đăng thông điệp: đã biết, đã tạm đóng quán, sẽ cập nhật trước trưa mai'},
             {k:'c',t:'Yêu cầu nhân viên quán lên mạng bình luận bênh vực công ty'},{k:'d',t:'Liên hệ nền tảng để báo cáo video vi phạm và xin gỡ xuống'}],
    answer:'b', why:{a:'Đoán nguyên nhân khi chưa kiểm tra dễ thành lời chối bị bóc mẽ.',
      b:'Đúng. Ba ý của thông điệp giữ chỗ: biết, làm, hẹn giờ.',
      c:'Nhân viên bênh vực bị phát hiện sẽ làm khủng hoảng nặng thêm.',
      d:'Xin gỡ video của khách bị coi là che giấu.'} },
  { type:'calc', stem:'Video có 3.000 lượt chia sẻ sau 1 giờ và 18.000 lượt sau 3 giờ. Trung bình mỗi giờ trong khoảng từ giờ thứ 1 đến giờ thứ 3 có thêm bao nhiêu lượt chia sẻ?',
    unit:'lượt/giờ', ans:7500, tol:1, wrong:[[6000,'SAI_MAU_SO'],[9000,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Lượt tăng thêm = 18.000 − 3.000 = 15.000.','Số giờ = 3 − 1 = 2 giờ.','15.000 ÷ 2 = <b>7.500 lượt/giờ</b>.'] },
  { type:'mcq', stem:'Vì sao thông điệp giữ chỗ không nên đoán nguyên nhân?',
    options:[{k:'a',t:'Vì đoán sai sẽ phải rút lại, mất thêm lòng tin lần thứ hai'},{k:'b',t:'Vì theo quy định công ty không được nói nguyên nhân trước 48 giờ'},
             {k:'c',t:'Vì khách hàng không quan tâm tới nguyên nhân của sự việc'},{k:'d',t:'Vì nêu nguyên nhân làm bài đăng quá dài, ít người đọc hết'}],
    answer:'a', why:{a:'Đúng. Lời giải thích sai trong giờ đầu thường thành khủng hoảng thứ hai.',
      b:'Không có quy định chung như vậy; đây là nguyên tắc nghề.',
      c:'Khách rất quan tâm, nên cần hẹn giờ trả lời thay vì đoán.',
      d:'Độ dài là phụ; rủi ro là nói sai.'} },
  { type:'mcq', stem:'Ba quản lý của Nồi Đỏ trả lời báo chí ba kiểu khác nhau. Hậu quả chính là gì?',
    options:[{k:'a',t:'Báo chí có nhiều nguồn nên đưa tin khách quan hơn'},{k:'b',t:'Không sao, miễn là cả ba người đều thể hiện thái độ cầu thị và xin lỗi khách hàng'},
             {k:'c',t:'Khách thấy công ty minh bạch vì ai cũng dám lên tiếng'},{k:'d',t:'Mâu thuẫn giữa các lời nói thành câu chuyện mới, khó kiểm soát'}],
    answer:'d', why:{a:'Nhiều phiên bản không làm tin khách quan hơn, chỉ rối hơn.',
      b:'Thái độ tốt không che được chi tiết mâu thuẫn.',
      c:'Minh bạch là nói một sự thật, không phải nhiều phiên bản.',
      d:'Đúng. Một giọng nói, một người phát ngôn là nguyên tắc cơ bản.'} },
  { type:'mcq', stem:'Ai là người phù hợp nhất để ký thông điệp giữ chỗ của Nồi Đỏ?',
    options:[{k:'a',t:'Quản lý quán Cầu Giấy vì là người gần sự việc nhất'},{k:'b',t:'Admin fanpage vì là người trả lời nhanh nhất lúc đêm'},
             {k:'c',t:'Giám đốc điều hành — người có quyền đóng quán ngay'},{k:'d',t:'Đại diện đối tác cung cấp dịch vụ diệt côn trùng'}],
    answer:'c', why:{a:'Quản lý quán có thể bị coi là người có lỗi, và thiếu thẩm quyền.',
      b:'Admin viết giúp được, nhưng lời chính thức cần người có quyền.',
      c:'Đúng. Người nói phải là người quyết định được hành động vừa hứa.',
      d:'Đẩy sang đối tác trông như đổ trách nhiệm.'} },
  { type:'mcq', stem:'Một hãng nước uống hư cấu thấy tin đồn "chai có hoá chất" lúc 23 giờ, chưa rõ thật giả. Lựa chọn nào hợp nhất?',
    options:[{k:'a',t:'Im lặng cho tới khi chắc chắn tin đồn là sai rồi mới lên tiếng'},{k:'b',t:'Lập tức khẳng định tin đồn sai và doạ kiện người tung tin'},
             {k:'c',t:'Nói đã biết, đang kiểm tra lô liên quan, hẹn giờ công bố kết quả'},{k:'d',t:'Tung chương trình khuyến mãi để lấn át tin đồn trên mạng'}],
    answer:'c', why:{a:'Chờ chắc chắn có thể mất cả ngày; khoảng trống bị lấp bằng tin đồn.',
      b:'Khẳng định khi chưa kiểm tra rất rủi ro nếu tin đồn đúng một phần.',
      c:'Đúng. Thông điệp giữ chỗ áp dụng cả khi chưa biết thật giả.',
      d:'Khuyến mãi giữa khủng hoảng an toàn bị coi là vô cảm.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kn09-07', skill:'comm', read:'6 phút', t:'Lời xin lỗi này có thật lòng không?',
  situation:'Hãng thời trang hư cấu Lụa Mây bị phát hiện dùng ảnh của một nhà thiết kế trẻ mà không xin phép. Bản xin lỗi đầu tiên viết: "Chúng tôi rất tiếc nếu sự việc gây hiểu lầm cho một số khách hàng." Trong 24 giờ, bài xin lỗi nhận 4.000 bình luận, phần lớn là giận dữ hơn trước. Nhóm truyền thông không hiểu vì sao "xin lỗi rồi mà vẫn bị chửi".',
  concept:{ name:'Bốn phần của một lời xin lỗi thật',
    body:'Lời xin lỗi làm dịu khủng hoảng khi có đủ bốn phần: <b>nhận đúng lỗi</b> bằng tên gọi cụ thể ("chúng tôi đã dùng ảnh của bạn X mà không xin phép"); <b>nói lời xin lỗi với đúng người</b> bị hại, không phải với "một số khách hàng"; <b>sửa hậu quả</b> (gỡ ảnh, trả phí, ghi công); và <b>thay đổi để không lặp lại</b>. Các cụm như "rất tiếc nếu", "gây hiểu lầm", "một số người cảm thấy" chuyển lỗi sang cảm xúc người nghe — đó là lời xin lỗi giả, và người đọc nhận ra ngay.' },
  example:'Bản thứ hai của Lụa Mây: "Chúng tôi đã dùng 6 ảnh của nhà thiết kế Minh Thư khi chưa xin phép. Đó là lỗi của chúng tôi. Chúng tôi đã gỡ ảnh, trả phí sử dụng gấp đôi mức bạn ấy đề nghị và ghi tên bạn ấy trong bộ sưu tập. Từ nay mọi hình ảnh bên ngoài đều qua kiểm tra bản quyền." Nhà thiết kế chia sẻ lại bài và nói đã nhận được lời xin lỗi.',
  takeaway:'Xin lỗi thật: gọi đúng tên lỗi, nói với đúng người, sửa hậu quả, và thay đổi để không lặp lại.',
  apply:'Tìm một lời xin lỗi của doanh nghiệp bạn từng đọc. Trong 60 giây, chỉ ra nó có và thiếu phần nào trong bốn phần.',
  mistakes:['Dùng "rất tiếc nếu" và "gây hiểu lầm" để né nhận lỗi.','Xin lỗi chung chung mà không có hành động sửa hậu quả.'],
  q:[
  { type:'mcq', stem:'Vì sao bản xin lỗi đầu tiên của Lụa Mây làm người đọc giận hơn?',
    options:[{k:'a',t:'Vì đăng quá muộn, sau khi sự việc đã lan rộng trên mạng và báo chí đã vào cuộc'},{k:'b',t:'Vì câu chữ né lỗi, đẩy vấn đề sang "hiểu lầm" của khách hàng'},
             {k:'c',t:'Vì bài xin lỗi quá ngắn, cần viết dài và cảm xúc hơn'},{k:'d',t:'Vì xin lỗi là thừa nhận yếu kém, khách sẽ càng tấn công'}],
    answer:'b', why:{a:'Thời điểm có thể chưa tốt, nhưng câu chữ mới là thứ khiến người đọc giận.',
      b:'Đúng. "Rất tiếc nếu... gây hiểu lầm" không nhận lỗi và không nói với người bị hại.',
      c:'Dài và cảm xúc mà vẫn né lỗi thì còn tệ hơn.',
      d:'Lời xin lỗi thật thường làm khủng hoảng dịu đi, không phải nặng thêm.'} },
  { type:'mcq', stem:'Bạn viết lại bản xin lỗi. Câu mở đầu nào bạn chọn?',
    options:[{k:'a',t:'"Chúng tôi đã dùng 6 ảnh của Minh Thư khi chưa xin phép. Đó là lỗi của chúng tôi."'},{k:'b',t:'"Lụa Mây luôn tôn trọng bản quyền và sự sáng tạo của các nghệ sĩ trẻ."'},
             {k:'c',t:'"Do sơ suất của một đối tác, một số hình ảnh đã được sử dụng chưa đúng."'},{k:'d',t:'"Chúng tôi thành thật xin lỗi vì những cảm xúc tiêu cực trong mấy ngày qua."'}],
    answer:'a', why:{a:'Đúng. Gọi đúng tên lỗi, đúng người, nhận trách nhiệm không điều kiện.',
      b:'Tuyên bố giá trị trái ngược với việc vừa làm, nghe như chối.',
      c:'Đổ cho đối tác và dùng thể bị động là né lỗi.',
      d:'Xin lỗi vì "cảm xúc" của người khác chứ không vì việc mình làm.'} },
  { type:'mcq', stem:'Cụm từ nào là dấu hiệu của một lời xin lỗi giả?',
    options:[{k:'a',t:'"Chúng tôi đã sai khi làm điều này"'},{k:'b',t:'"Chúng tôi đã liên hệ trực tiếp với người bị ảnh hưởng"'},
             {k:'c',t:'"Từ tuần sau chúng tôi áp dụng quy trình kiểm tra mới"'},{k:'d',t:'"Rất tiếc nếu một số người cảm thấy bị xúc phạm"'}],
    answer:'d', why:{a:'Nhận lỗi trực tiếp là dấu hiệu của lời xin lỗi thật.',
      b:'Nói với đúng người bị hại là một phần cần có.',
      c:'Cam kết thay đổi cụ thể là phần thứ tư.',
      d:'Đúng. "Rất tiếc nếu... cảm thấy" đặt lỗi vào cảm xúc người nghe.'} },
  { type:'calc', stem:'Nhà thiết kế đề nghị phí 3 triệu đồng cho mỗi ảnh. Lụa Mây trả gấp đôi cho 6 ảnh. Tổng số tiền là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:36, tol:0.1, wrong:[[18,'SAI_TINH_TOAN'],[6,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Phí gấp đôi mỗi ảnh = 3 × 2 = 6 triệu.','6 ảnh × 6 triệu = <b>36 triệu đồng</b>.'] },
  { type:'mcq', stem:'Một hãng hàng không hư cấu làm hỏng xe lăn của một hành khách. Phần nào quan trọng nhất cần có ngoài lời xin lỗi?',
    options:[{k:'a',t:'Một video cảm xúc về cam kết phục vụ người khuyết tật'},{k:'b',t:'Tặng hành khách vé hạng thương gia cho chuyến bay sau'},
             {k:'c',t:'Sửa hoặc thay xe lăn ngay và đổi quy trình xếp dỡ thiết bị'},{k:'d',t:'Giải thích xe lăn bị hỏng do đối tác mặt đất xử lý'}],
    answer:'c', why:{a:'Video cảm xúc mà chưa sửa hậu quả sẽ bị coi là làm màu.',
      b:'Vé tặng không giải quyết việc người đó đang không có xe lăn.',
      c:'Đúng. Sửa hậu quả trực tiếp và thay đổi để không lặp lại.',
      d:'Khách mua vé của hãng; đẩy sang đối tác là né trách nhiệm.'} },
  { type:'mcq', stem:'Vì sao lời xin lỗi nên nói với đúng người bị hại thay vì "quý khách hàng"?',
    options:[{k:'a',t:'Vì nói chung chung làm lỗi mờ đi, người bị hại cảm thấy bị lờ'},{k:'b',t:'Vì nêu tên người bị hại giúp bài đăng tiếp cận nhiều người hơn'},
             {k:'c',t:'Vì khách hàng khác không cần biết sự việc cụ thể là gì'},{k:'d',t:'Vì theo quy định, lời xin lỗi phải ghi rõ họ tên người nhận'}],
    answer:'a', why:{a:'Đúng. Xin lỗi "mọi người" là không xin lỗi ai cả.',
      b:'Mục tiêu không phải tăng tiếp cận.',
      c:'Minh bạch với mọi người vẫn cần; vấn đề là đúng người nhận.',
      d:'Không có quy định chung như vậy; đây là nguyên tắc của lời xin lỗi thật.'} },
  { type:'mcq', stem:'Sau bản xin lỗi thứ hai, nhà thiết kế chia sẻ lại bài. Điều này có ý nghĩa gì?',
    options:[{k:'a',t:'Khủng hoảng đã kết thúc hoàn toàn, không cần làm gì thêm'},{k:'b',t:'Nhà thiết kế đã được trả tiền để nói tốt cho Lụa Mây'},
             {k:'c',t:'Người bị hại chấp nhận, lời của họ đáng tin hơn lời công ty'},{k:'d',t:'Lụa Mây nên dùng ảnh của nhà thiết kế cho chiến dịch mới'}],
    answer:'c', why:{a:'Vẫn phải thực hiện cam kết thay đổi quy trình, nếu không sẽ tái phát.',
      b:'Trả phí sử dụng ảnh khác với mua lời khen; suy diễn không có căn cứ.',
      c:'Đúng. Lời chấp nhận từ người bị hại là tín hiệu mạnh nhất với công chúng.',
      d:'Dùng ngay người bị hại cho quảng cáo dễ bị coi là lợi dụng.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kn09-08', skill:'comm', read:'6 phút', t:'Khi nào im lặng là sai?',
  situation:'Chuỗi siêu thị mini hư cấu Tươi Mỗi Ngày gặp hai chuyện trong một tháng. Chuyện 1: một tài khoản 200 người theo dõi viết rằng "nghe nói" rau ở đây phun thuốc, bài có 12 lượt thích. Chuyện 2: một video của khách quay nhân viên thay nhãn hạn dùng trên hộp thịt, 40.000 lượt xem trong nửa ngày. Giám đốc muốn phản hồi mạnh cả hai.',
  concept:{ name:'Ngưỡng phản hồi',
    body:'Không phải lời chê nào cũng cần phản hồi công khai; phản hồi to một chuyện nhỏ có thể khiến nhiều người biết hơn. Hãy xét ba câu: <b>có bằng chứng cụ thể không</b> (video, ảnh, hoá đơn); <b>có đụng tới an toàn hay pháp lý không</b>; và <b>có đang lan ra ngoài nhóm nhỏ không</b>. Nếu cả ba đều "không", theo dõi và trả lời riêng. Nếu có bằng chứng về an toàn, hoặc đang lan nhanh, im lặng là sai — vì im lặng lúc đó bị đọc là thừa nhận hoặc coi thường.' },
  example:'Chuyện 1: không bằng chứng, không lan, chỉ 12 lượt thích — Tươi Mỗi Ngày nhắn riêng mời người viết xem giấy kiểm nghiệm, không đăng công khai. Chuyện 2: có video, đụng tới an toàn thực phẩm, 40.000 lượt xem — phải lên tiếng trong vài giờ: tạm đình chỉ nhân viên và quản lý ca, niêm phong lô thịt, mời đơn vị độc lập kiểm tra.',
  takeaway:'Im lặng được khi chuyện nhỏ, không bằng chứng; có bằng chứng về an toàn hoặc đang lan nhanh thì im lặng là sai.',
  apply:'Nhớ một lời chê trên fanpage bạn từng thấy. Trong 60 giây, trả lời ba câu hỏi ngưỡng và nói nên im hay nói.',
  mistakes:['Phản hồi ầm ĩ một bài chê nhỏ khiến nhiều người biết hơn.','Im lặng khi đã có bằng chứng về an toàn đang lan rộng.'],
  q:[
  { type:'mcq', stem:'Giám đốc muốn phản hồi công khai và mạnh mẽ cả hai chuyện. Rủi ro lớn nhất với chuyện 1 là gì?',
    options:[{k:'a',t:'Phản hồi công khai làm nhiều người biết tới tin đồn vốn chỉ vài chục người đọc'},{k:'b',t:'Tài khoản đó sẽ kiện ngược lại công ty vì bị nhắc tên'},
             {k:'c',t:'Tốn chi phí và thời gian của ban lãnh đạo để soạn, duyệt một thông cáo chính thức cho chuyện này'},{k:'d',t:'Nhân viên sẽ phản đối vì phải làm thêm vào cuối tuần'}],
    answer:'a', why:{a:'Đúng. Phản hồi to một tin đồn nhỏ là tự khuếch đại nó.',
      b:'Suy diễn không có căn cứ; rủi ro chính nằm ở chỗ khác.',
      c:'Chi phí viết không phải điều đáng lo.',
      d:'Không liên quan tới quyết định có nên phản hồi.'} },
  { type:'mcq', stem:'Với chuyện 2 (video thay nhãn hạn dùng), bạn chọn gì?',
    options:[{k:'a',t:'Im lặng, chờ vài ngày cho video trôi đi trên mạng xã hội'},{k:'b',t:'Nhắn riêng người quay video, đề nghị quà để gỡ bài'},
             {k:'c',t:'Đăng bài khẳng định mọi sản phẩm của chuỗi luôn đảm bảo an toàn, có đủ giấy tờ'},{k:'d',t:'Lên tiếng trong vài giờ, đình chỉ nhân viên, niêm phong lô thịt'}],
    answer:'d', why:{a:'Có bằng chứng về an toàn và đang lan — im lặng bị đọc là thừa nhận.',
      b:'Mua gỡ bài bị lộ ra sẽ thành khủng hoảng thứ hai.',
      c:'Khẳng định chung chung trái ngược với video, không ai tin.',
      d:'Đúng. Đủ cả ba dấu hiệu, cần hành động và nói công khai.'} },
  { type:'mcq', stem:'Câu nào KHÔNG thuộc ba câu hỏi ngưỡng phản hồi?',
    options:[{k:'a',t:'Có bằng chứng cụ thể như video, ảnh hay hoá đơn không?'},{k:'b',t:'Người đăng có phải là khách hàng thân thiết của mình không?'},
             {k:'c',t:'Có đụng tới an toàn hay pháp lý không?'},{k:'d',t:'Có đang lan ra ngoài nhóm nhỏ ban đầu không?'}],
    answer:'b', why:{a:'Bằng chứng là câu hỏi đầu tiên.',
      b:'Đúng. Ai đăng không quan trọng bằng nội dung, bằng chứng và độ lan.',
      c:'An toàn và pháp lý là câu hỏi thứ hai.',
      d:'Độ lan là câu hỏi thứ ba.'} },
  { type:'calc', stem:'Chuyện 1 có 12 lượt thích trên tài khoản 200 người theo dõi. Tỉ lệ tương tác trên người theo dõi là bao nhiêu phần trăm?',
    unit:'%', ans:6, tol:0.1, wrong:[[1666.7,'SAI_MAU_SO'],[0.06,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = lượt thích ÷ người theo dõi.','12 ÷ 200 = 0,06 = <b>6%</b> — trên một tập người đọc rất nhỏ.'] },
  { type:'mcq', stem:'Một quán ăn hư cấu bị một khách chê "phục vụ chậm" trên nhóm review 500.000 thành viên, bài có 30 lượt thích. Cách làm hợp lý?',
    options:[{k:'a',t:'Đăng bài dài trên fanpage giải thích lý do phục vụ chậm hôm đó'},{k:'b',t:'Báo cáo bài viết với quản trị nhóm để xoá đi'},
             {k:'c',t:'Trả lời ngắn, lịch sự dưới bài và nhắn riêng để bù đắp'},{k:'d',t:'Không làm gì, vì phục vụ chậm là chuyện nhỏ ai cũng gặp'}],
    answer:'c', why:{a:'Đăng lên fanpage tự đưa chuyện nhỏ tới khách của mình.',
      b:'Xin xoá bài chê thật dễ bị chụp lại và chia sẻ.',
      c:'Đúng. Trả lời tại chỗ, tương xứng quy mô, xử lý riêng với khách.',
      d:'Nhóm lớn nên có người đọc; một câu trả lời lịch sự cho thấy quán lắng nghe.'} },
  { type:'mcq', stem:'Vì sao im lặng khi đã có bằng chứng về an toàn lại nguy hiểm?',
    options:[{k:'a',t:'Vì đối thủ sẽ tận dụng khoảng lặng để chạy quảng cáo so sánh ngay trong tuần đó'},{k:'b',t:'Vì nền tảng mạng xã hội sẽ khoá fanpage nếu không phản hồi'},
             {k:'c',t:'Vì báo chí bắt buộc phải có ý kiến doanh nghiệp mới được đăng'},{k:'d',t:'Vì người đọc hiểu im lặng là thừa nhận hoặc không quan tâm tới khách'}],
    answer:'d', why:{a:'Có thể xảy ra, nhưng không phải rủi ro chính.',
      b:'Nền tảng không khoá trang vì không phản hồi.',
      c:'Báo vẫn đăng và ghi "chưa liên lạc được".',
      d:'Đúng. Khi có bằng chứng, im lặng có nghĩa — và nghĩa đó bất lợi.'} },
  { type:'mcq', stem:'Tin đồn ở chuyện 1 bỗng được một trang tin 2 triệu người theo dõi đăng lại. Bạn nên làm gì?',
    options:[{k:'a',t:'Chuyển sang phản hồi công khai, kèm giấy kiểm nghiệm rau cụ thể'},{k:'b',t:'Tiếp tục im lặng như trước, vì phản hồi lúc này chỉ làm tin đồn lan thêm'},
             {k:'c',t:'Chỉ nhắn riêng người viết đầu tiên như cách ban đầu'},{k:'d',t:'Yêu cầu trang tin gỡ bài, nếu không sẽ kiện ngay'}],
    answer:'a', why:{a:'Đúng. Độ lan đã vượt ngưỡng; câu trả lời phải đi kèm bằng chứng.',
      b:'Ngưỡng là để xét lại khi tình hình đổi, không phải quyết định một lần.',
      c:'Nhắn riêng không còn tương xứng với quy mô lan truyền mới.',
      d:'Đe doạ kiện thường khuếch đại câu chuyện.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:kn09-09', skill:'channel', read:'7 phút', t:'Trả lời 3.000 bình luận giận dữ thế nào?',
  situation:'Ứng dụng đặt vé xe hư cấu XeVề bị lỗi hệ thống đêm 27 Tết, 5.000 vé bị hủy. Bài thông báo trên fanpage có 3.000 bình luận trong 6 giờ. Admin đang dán cùng một câu "Rất tiếc về trải nghiệm của bạn, vui lòng inbox" dưới mọi bình luận. Khách chụp màn hình hàng chục câu giống hệt nhau và đăng lên các nhóm với tít "XeVề trả lời bằng máy".',
  concept:{ name:'Phản hồi mạng xã hội trong khủng hoảng',
    body:'Trên mạng xã hội, mỗi câu trả lời là công khai và bị chụp lại. Ba nguyên tắc: <b>một bài chính được ghim</b> cập nhật liên tục, để mọi người biết tìm thông tin ở đâu; <b>trả lời theo nhóm vấn đề</b> (hoàn tiền, đổi chuyến, thời gian xử lý) bằng câu có thông tin thật, thay vì một câu mẫu vô nghĩa; và <b>chuyển trường hợp riêng sang kênh riêng</b> nhưng kèm cách làm cụ thể. Không xoá bình luận chê, không tranh cãi, không đùa. Tốc độ cần đi cùng thông tin — trả lời nhanh mà rỗng còn tệ hơn trả lời chậm mà có ích.' },
  example:'XeVề ghim bài: "5.000 vé bị hủy sẽ được hoàn 100% trong 48 giờ, kèm mã giảm 50.000đ. Đổi chuyến: bấm mục Vé của tôi, chọn Đổi miễn phí." Admin chia bình luận thành 3 nhóm và trả lời bằng câu có đường dẫn cụ thể. Sau 12 giờ, bình luận mới mỗi giờ giảm từ 500 xuống còn 80.',
  takeaway:'Trên mạng xã hội, mỗi câu trả lời đều bị chụp lại: trả lời ít câu mẫu, nhiều thông tin thật.',
  apply:'Viết trong 60 giây một câu trả lời bình luận cho khách bị hủy vé, có thông tin cụ thể thay vì "vui lòng inbox".',
  mistakes:['Dán một câu mẫu giống hệt dưới mọi bình luận.','Xoá bình luận chê hoặc tranh cãi với khách đang giận.'],
  q:[
  { type:'mcq', stem:'Vì sao cách admin XeVề trả lời lại thành chuyện mới?',
    options:[{k:'a',t:'Vì admin trả lời quá chậm so với tốc độ bình luận của khách'},{k:'b',t:'Vì câu mẫu lặp lại không có thông tin, bị chụp lại như bằng chứng thờ ơ'},
             {k:'c',t:'Vì khách không thích nhắn tin riêng với công ty vào dịp Tết'},{k:'d',t:'Vì trong khủng hoảng, fanpage không nên trả lời bình luận nào, chỉ nên đăng thông báo'}],
    answer:'b', why:{a:'Họ trả lời nhanh; vấn đề là câu trả lời rỗng.',
      b:'Đúng. Câu mẫu lặp lại cho thấy không ai thật sự nghe.',
      c:'Kênh riêng có ích nếu kèm cách làm cụ thể.',
      d:'Không trả lời gì còn tệ hơn; vấn đề là nội dung trả lời.'} },
  { type:'mcq', stem:'Bạn tiếp quản fanpage XeVề. Việc đầu tiên bạn làm là gì?',
    options:[{k:'a',t:'Tắt tính năng bình luận trên fanpage để dừng làn sóng chỉ trích trong đêm'},{k:'b',t:'Xoá các bình luận nặng lời để fanpage trông bớt tiêu cực'},
             {k:'c',t:'Tuyển thêm admin để dán câu mẫu nhanh hơn cho kịp khách'},{k:'d',t:'Ghim một bài có thông tin hoàn tiền, đổi chuyến và thời hạn cụ thể'}],
    answer:'d', why:{a:'Tắt bình luận bị coi là bịt miệng, khách chuyển sang nhóm khác chửi.',
      b:'Xoá bình luận bị chụp lại, thành bằng chứng che giấu.',
      c:'Nhanh hơn với câu rỗng chỉ nhân lên vấn đề.',
      d:'Đúng. Một nguồn thông tin chính giúp mọi câu trả lời sau có chỗ dựa.'} },
  { type:'calc', stem:'XeVề hoàn 100% cho 5.000 vé, giá trung bình 350.000đ/vé, và tặng mỗi vé mã 50.000đ. Nếu 60% khách dùng mã, tổng chi phí là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:1900, tol:1, wrong:[[2000,'QUEN_TI_LE_CHUYEN_DOI'],[1750,'QUEN_CHI_PHI_KHUYEN_MAI']], errors:['QUEN_TI_LE_CHUYEN_DOI','QUEN_CHI_PHI_KHUYEN_MAI'],
    steps:['Hoàn tiền = 5.000 × 350.000 = 1.750 triệu.','Mã được dùng = 5.000 × 60% × 50.000 = 150 triệu.','Tổng = 1.750 + 150 = <b>1.900 triệu đồng</b>.'] },
  { type:'mcq', stem:'Câu trả lời bình luận nào tốt nhất cho khách hỏi "Bao giờ tôi được hoàn tiền?"',
    options:[{k:'a',t:'"Rất tiếc về trải nghiệm của bạn, vui lòng inbox để được hỗ trợ"'},{k:'b',t:'"XeVề luôn đặt quyền lợi khách hàng lên hàng đầu, mong bạn thông cảm"'},
             {k:'c',t:'"Tiền hoàn về ví trong 48 giờ. Quá hạn, bạn nhắn mã vé vào đây, mình xử lý"'},{k:'d',t:'"Lỗi do đối tác máy chủ, chúng tôi cũng là nạn nhân như bạn"'}],
    answer:'c', why:{a:'Câu mẫu không trả lời câu hỏi thời gian.',
      b:'Khẩu hiệu không có thông tin.',
      c:'Đúng. Trả lời đúng câu hỏi, có thời hạn và bước tiếp theo.',
      d:'Đổ lỗi đối tác làm khách giận thêm; họ mua vé của XeVề.'} },
  { type:'mcq', stem:'Một khách bình luận chửi tục và vu cáo XeVề lừa đảo. Admin nên làm gì?',
    options:[{k:'a',t:'Trả lời bình tĩnh bằng thông tin hoàn tiền, không tranh cãi lại'},{k:'b',t:'Trả lời đanh thép để bảo vệ danh dự nhân viên công ty'},
             {k:'c',t:'Chặn tài khoản và xoá hết lịch sử bình luận của người đó để tránh lan thêm'},{k:'d',t:'Đùa nhẹ nhàng cho không khí bớt căng thẳng trên fanpage'}],
    answer:'a', why:{a:'Đúng. Người đọc khác đang nhìn; câu trả lời bình tĩnh có thông tin thuyết phục họ.',
      b:'Cãi nhau công khai tạo ảnh chụp màn hình xấu.',
      c:'Chặn và xoá khi đang khủng hoảng dễ bị coi là che giấu.',
      d:'Đùa khi khách mất vé về quê ăn Tết là vô cảm.'} },
  { type:'mcq', stem:'Vì sao nên chia bình luận thành các nhóm vấn đề?',
    options:[{k:'a',t:'Để báo cáo cho ban giám đốc số lượng bình luận tiêu cực theo từng loại mỗi giờ'},{k:'b',t:'Để mỗi nhóm có câu trả lời đúng thông tin, trả lời nhanh mà không rỗng'},
             {k:'c',t:'Để quyết định nhóm nào nên xoá bớt khỏi fanpage cho gọn'},{k:'d',t:'Để chỉ trả lời nhóm lớn nhất và bỏ qua các nhóm còn lại'}],
    answer:'b', why:{a:'Báo cáo là phụ; mục đích chính là trả lời đúng.',
      b:'Đúng. Soạn sẵn câu có thông tin cho từng nhóm giúp nhanh và vẫn có ích.',
      c:'Không xoá bình luận chê trong khủng hoảng.',
      d:'Bỏ qua nhóm nhỏ làm họ thấy bị lờ.'} },
  { type:'mcq', stem:'Sau 12 giờ, bình luận mới mỗi giờ giảm từ 500 xuống 80. Cách đọc hợp lý nhất?',
    options:[{k:'a',t:'Khủng hoảng đã kết thúc, có thể quay lại đăng nội dung khuyến mãi vé Tết để kéo khách về'},{k:'b',t:'Khách đã chán nên không còn quan tâm tới việc hoàn tiền'},
             {k:'c',t:'Thông tin rõ đang trả lời được thắc mắc, nhưng vẫn phải giữ lời hoàn trong 48 giờ'},{k:'d',t:'Số liệu chưa đủ tin, cần đợi thêm một tuần nữa mới kết luận'}],
    answer:'c', why:{a:'Đăng khuyến mãi khi tiền chưa hoàn sẽ châm lại cơn giận.',
      b:'Giảm bình luận không có nghĩa là hết quan tâm tiền của họ.',
      c:'Đúng. Tín hiệu tốt, nhưng lời hứa 48 giờ mới là bài kiểm tra thật.',
      d:'Xu hướng đủ rõ để đọc; vấn đề là không chủ quan.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:kn09-10', skill:'measure', read:'6 phút', t:'Khủng hoảng qua rồi, bạn học được gì?',
  situation:'Ba tháng sau vụ bánh có dị vật, hãng bánh hư cấu Hạt Vàng đã bán lại bình thường. Giám đốc muốn "quên đi cho nhanh". Trưởng phòng truyền thông đề nghị một buổi rút kinh nghiệm hai giờ, với dữ liệu: mất 9 giờ mới ra thông báo đầu tiên, 3 người phát ngôn nói 3 kiểu, và nhà máy mất 2 ngày mới truy được mã lô.',
  concept:{ name:'Rút kinh nghiệm không đổ lỗi',
    body:'Buổi rút kinh nghiệm (post-mortem) nhìn lại dòng thời gian: <b>chuyện gì xảy ra, lúc nào, ai quyết gì, dựa trên thông tin gì</b>. Mục tiêu là sửa hệ thống, không tìm người để phạt — nếu không, lần sau mọi người sẽ giấu thông tin. Đầu ra là vài thay đổi cụ thể có người chịu trách nhiệm và hạn chót: danh sách người phát ngôn, mẫu thông điệp giữ chỗ, quy trình truy lô, số điện thoại trực đêm. Cuối cùng là một buổi diễn tập để kiểm tra các thay đổi có chạy thật không.' },
  example:'Hạt Vàng đo ba mốc: 9 giờ tới thông báo đầu tiên, 48 giờ tới khi truy được lô, 3 người phát ngôn. Mục tiêu mới: dưới 2 giờ, dưới 12 giờ, 1 người. Họ lập nhóm trực khủng hoảng 5 người, soạn sẵn mẫu thông điệp, đưa mã lô lên hệ thống tra cứu. Sáu tháng sau diễn tập: thông báo giả ra sau 1 giờ 40 phút, truy lô mất 10 giờ.',
  takeaway:'Khủng hoảng chỉ đáng giá khi thành thay đổi cụ thể; rút kinh nghiệm để sửa hệ thống, không để tìm người chịu phạt.',
  apply:'Nghĩ về một lần mọi việc đi sai trong công việc của bạn. Trong 60 giây, kể dòng thời gian và nêu một thay đổi hệ thống.',
  mistakes:['Kết thúc khủng hoảng bằng việc kỷ luật một người rồi thôi.','Rút kinh nghiệm xong nhưng không diễn tập để kiểm tra.'],
  q:[
  { type:'mcq', stem:'Vì sao "quên đi cho nhanh" là cách làm rủi ro sau khủng hoảng?',
    options:[{k:'a',t:'Vì báo chí sẽ viết lại vụ việc vào đúng ngày kỷ niệm một năm'},{k:'b',t:'Vì khách hàng sẽ không mua lại cho tới khi công ty tổ chức họp'},
             {k:'c',t:'Vì những lỗ hổng lần này vẫn còn nguyên cho lần khủng hoảng sau'},{k:'d',t:'Vì theo quy định, doanh nghiệp phải nộp báo cáo khủng hoảng'}],
    answer:'c', why:{a:'Có thể, nhưng không phải lý do chính.',
      b:'Khách đã mua lại bình thường, như tình huống cho thấy.',
      c:'Đúng. 9 giờ im lặng, 3 người phát ngôn, 2 ngày truy lô — lần sau sẽ lặp lại.',
      d:'Không nên khẳng định quy định cụ thể như lý do chính.'} },
  { type:'mcq', stem:'Bạn chủ trì buổi rút kinh nghiệm. Bạn làm gì đầu tiên?',
    options:[{k:'a',t:'Hỏi ai là người để thông báo chậm 9 giờ để xử lý kỷ luật'},{k:'b',t:'Dựng lại dòng thời gian: lúc nào, ai biết gì, ai quyết gì, dựa trên gì'},
             {k:'c',t:'Trình chiếu các bài báo tiêu cực để mọi người thấy hậu quả và thấy trách nhiệm của mình'},{k:'d',t:'Mời chuyên gia bên ngoài chấm điểm cách công ty đã xử lý'}],
    answer:'b', why:{a:'Tìm người phạt làm mọi người phòng thủ và giấu thông tin.',
      b:'Đúng. Dòng thời gian cho thấy lỗ hổng nằm ở đâu trong hệ thống.',
      c:'Gây áp lực cảm xúc, không giúp tìm nguyên nhân.',
      d:'Chuyên gia có thể giúp, nhưng trước hết cần dữ kiện nội bộ.'} },
  { type:'calc', stem:'Thời gian tới thông báo đầu tiên giảm từ 9 giờ xuống 1 giờ 40 phút trong buổi diễn tập. Thời gian đã giảm bao nhiêu phần trăm (làm tròn 1 chữ số thập phân)?',
    unit:'%', ans:81.5, tol:0.2, wrong:[[18.5,'NHAM_TI_LE_ROI'],[440,'SAI_MAU_SO']], errors:['NHAM_TI_LE_ROI','SAI_MAU_SO'],
    steps:['Đổi ra phút: 9 giờ = 540 phút; 1 giờ 40 phút = 100 phút.','Giảm = 540 − 100 = 440 phút.','440 ÷ 540 ≈ 0,815 = <b>81,5%</b>.'] },
  { type:'mcq', stem:'Đầu ra nào của buổi rút kinh nghiệm có giá trị nhất?',
    options:[{k:'a',t:'Một báo cáo dài ghi lại toàn bộ diễn biến để lưu trữ'},{k:'b',t:'Một danh sách lời cảm ơn các phòng ban đã vất vả'},
             {k:'c',t:'Một kết luận được cả ban đồng ý: "cần phản ứng nhanh hơn lần sau"'},{k:'d',t:'Vài thay đổi cụ thể, có người chịu trách nhiệm và có hạn chót'}],
    answer:'d', why:{a:'Báo cáo dài dễ nằm trong ngăn kéo không ai đọc.',
      b:'Ghi nhận công sức là tốt, nhưng không làm hệ thống khá hơn.',
      c:'Kết luận không có người, không có hạn thì không ai làm.',
      d:'Đúng. Thay đổi chỉ xảy ra khi có người làm và hạn chót.'} },
  { type:'mcq', stem:'Vì sao cần diễn tập sau khi đã có quy trình mới?',
    options:[{k:'a',t:'Để kiểm tra quy trình có chạy thật khi áp lực và nửa đêm không'},{k:'b',t:'Để quay video đăng lên mạng cho thấy công ty chuyên nghiệp'},
             {k:'c',t:'Vì đối tác bảo hiểm yêu cầu có diễn tập định kỳ mới chi trả bồi thường khủng hoảng'},{k:'d',t:'Để tìm ra ai trong nhóm trực làm chưa tốt và thay người'}],
    answer:'a', why:{a:'Đúng. Quy trình trên giấy thường vỡ ở chỗ không ai nghĩ tới — số máy trực, quyền đăng bài.',
      b:'Diễn tập là việc nội bộ, không phải để làm truyền thông.',
      c:'Không nên suy ra điều kiện bảo hiểm cụ thể.',
      d:'Mục tiêu là kiểm tra hệ thống, giống tinh thần không đổ lỗi.'} },
  { type:'mcq', stem:'Một chuỗi khách sạn hư cấu sau khủng hoảng chỉ sa thải quản lý ca trực. Nhiều khả năng điều gì xảy ra ở lần sau?',
    options:[{k:'a',t:'Nhân viên sẽ cẩn thận hơn nên khủng hoảng không lặp lại nữa'},{k:'b',t:'Khách hàng hài lòng vì thấy công ty đã xử lý nghiêm khắc'},
             {k:'c',t:'Người biết chuyện giấu thông tin lâu hơn vì sợ bị phạt'},{k:'d',t:'Báo chí đánh giá cao nên sẽ viết nhẹ tay hơn vào lần sau'}],
    answer:'c', why:{a:'Sợ hãi không sửa được lỗ hổng quy trình.',
      b:'Khách quan tâm việc nó có lặp lại không, hơn là ai bị đuổi.',
      c:'Đúng. Văn hoá đổ lỗi làm thông tin xấu tới chậm hơn — đúng thứ làm khủng hoảng nặng.',
      d:'Báo chí không "nợ" doanh nghiệp vì một lần kỷ luật.'} },
  { type:'mcq', stem:'Mốc đo nào giúp Hạt Vàng biết lần sau mình phản ứng tốt hơn?',
    options:[{k:'a',t:'Số bài báo tiêu cực trong tuần đầu so với lần trước'},{k:'b',t:'Thời gian tới thông báo đầu, thời gian truy lô, số người phát ngôn'},
             {k:'c',t:'Doanh số tháng sau khủng hoảng so với cùng kỳ năm trước'},{k:'d',t:'Số lượt thích và chia sẻ của bài xin lỗi so với các bài đăng thường ngày'}],
    answer:'b', why:{a:'Số bài báo phụ thuộc cả độ nghiêm trọng của vụ việc, khó so công bằng.',
      b:'Đúng. Đây là những thứ công ty kiểm soát được và đo được qua diễn tập.',
      c:'Doanh số chịu tác động của quá nhiều yếu tố khác.',
      d:'Lượt thích không đo tốc độ hay chất lượng xử lý.'} }
  ] }

]});
